import java.util.*;

class MyQueue {
    private Deque<Integer> in;
    private Deque<Integer> tmp;

    public MyQueue() {
        in = new ArrayDeque<>();
        tmp = new ArrayDeque<>();
    }

    public void push(int x) {
        // 每次 push 都整体翻转，让 x 落到栈底、队头留在栈顶
        while (!in.isEmpty()) tmp.push(in.pop());
        in.push(x);
        while (!tmp.isEmpty()) in.push(tmp.pop());
    }

    public int pop() {
        return in.pop();
    }

    public int peek() {
        return in.peek();
    }

    public boolean empty() {
        return in.isEmpty();
    }
}

import java.util.*;

class MyQueue {
    private Deque<Integer> in;    // 收
    private Deque<Integer> out;   // 发

    public MyQueue() {
        in = new ArrayDeque<>();
        out = new ArrayDeque<>();
    }

    public void push(int x) {
        in.push(x);
    }

    public int pop() {
        ensureOut();
        return out.pop();
    }

    public int peek() {
        ensureOut();
        return out.peek();
    }

    public boolean empty() {
        return in.isEmpty() && out.isEmpty();
    }

    // out 空了才把 in 整体倒过来，一次搬移服务多次 pop
    private void ensureOut() {
        if (out.isEmpty()) {
            while (!in.isEmpty()) out.push(in.pop());
        }
    }
}

import java.util.*;

class MyQueue {
    private Deque<Integer> in;
    private Deque<Integer> out;
    private int front;            // 队头值，让 peek 严格 O(1)

    public MyQueue() {
        in = new ArrayDeque<>();
        out = new ArrayDeque<>();
    }

    public void push(int x) {
        // 只有 in 为空时，新元素才是队头
        if (in.isEmpty()) front = x;
        in.push(x);
    }

    public int pop() {
        if (out.isEmpty()) {
            while (!in.isEmpty()) out.push(in.pop());
        }
        return out.pop();
    }

    public int peek() {
        // out 非空读 out，否则直接返回缓存的队头，完全不搬移
        if (!out.isEmpty()) return out.peek();
        return front;
    }

    public boolean empty() {
        return in.isEmpty() && out.isEmpty();
    }
}
